import{_ as o,o as a,c as r,ae as s}from"./chunks/framework.Co1PSFSm.js";const m=JSON.parse('{"title":"Escenarios y Casos de Uso","description":"","frontmatter":{},"headers":[],"relativePath":"user/escenarios.md","filePath":"user/escenarios.md"}'),n={name:"user/escenarios.md"};function i(t,e,c,d,l,p){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="escenarios-y-casos-de-uso" tabindex="-1">Escenarios y Casos de Uso <a class="header-anchor" href="#escenarios-y-casos-de-uso" aria-label="Permalink to &quot;Escenarios y Casos de Uso&quot;">​</a></h1><h3 id="escenario-a-vps-limpio-con-docker-✅" tabindex="-1">ESCENARIO A: VPS Limpio con Docker ✅ <a class="header-anchor" href="#escenario-a-vps-limpio-con-docker-✅" aria-label="Permalink to &quot;ESCENARIO A: VPS Limpio con Docker ✅&quot;">​</a></h3><p><strong>Perfil</strong>: Ubuntu 22.04, Docker activos, hosting dedicado. <strong>Resultado</strong>: Se ejecuta el comando de instalación e inmediatamente el Agente entra a modo operativo sin intervención manual.</p><h3 id="escenario-b-wordpress-instalado-manualmente-sin-docker-🔧" tabindex="-1">ESCENARIO B: WordPress Instalado Manualmente (sin Docker) 🔧 <a class="header-anchor" href="#escenario-b-wordpress-instalado-manualmente-sin-docker-🔧" aria-label="Permalink to &quot;ESCENARIO B: WordPress Instalado Manualmente (sin Docker) 🔧&quot;">​</a></h3><p><strong>Perfil</strong>: Cliente migrado de hosting compartido, Apache/Nginx + PHP + MySQL directo en el OS.</p><p><strong>¿Qué respalda el agente?</strong></p><ul><li><code>/var/www/html</code> — Archivos PHP y temas de WordPress</li><li><code>/etc/nginx</code> o <code>/etc/apache2</code> — Configuración del servidor web</li><li><code>/etc/letsencrypt</code> — Certificados SSL activos</li><li><code>/var/lib/mysql</code> — Bases de datos MySQL</li><li><code>/etc/php</code> — Configuración de PHP</li></ul><p><strong>Nota:</strong> El agente instala Docker automáticamente de ser necesario para poder correr, pero no pausa MySQL o Apache en la máquina anfitrión, operando en modo <em>live</em>.</p><h3 id="escenario-c-sistema-personalizado-sin-docker-node-js-python-etc-🔧" tabindex="-1">ESCENARIO C: Sistema Personalizado sin Docker (Node.js, Python, etc.) 🔧 <a class="header-anchor" href="#escenario-c-sistema-personalizado-sin-docker-node-js-python-etc-🔧" aria-label="Permalink to &quot;ESCENARIO C: Sistema Personalizado sin Docker (Node.js, Python, etc.) 🔧&quot;">​</a></h3><p><strong>Perfil</strong>: Aplicación Node.js levantada con PM2, sin Docker.</p><p><strong>¿Qué respaldar?</strong></p><ul><li><code>/home/app</code> o <code>/var/www/app</code> — Código fuente</li><li><code>/etc/nginx</code> — Configuración proxy</li><li><code>~/.pm2</code> — Configuración de PM2</li></ul><p><strong>Configuración</strong>: Al no haber contenedores Docker, usa &quot;Select All (Dynamic)&quot; para abarcar todo el servidor.</p><h3 id="escenario-h-infraestructura-critica-windows-ad-pfsense-7tb-ssd-🏢" tabindex="-1">ESCENARIO H: Infraestructura Crítica Windows (AD + pfSense + 7TB SSD) 🏢 <a class="header-anchor" href="#escenario-h-infraestructura-critica-windows-ad-pfsense-7tb-ssd-🏢" aria-label="Permalink to &quot;ESCENARIO H: Infraestructura Crítica Windows (AD + pfSense + 7TB SSD) 🏢&quot;">​</a></h3><p><strong>Perfil</strong>: Cliente con Windows Server robusto, Active Directory, y 7TB SSD. <strong>Producto</strong>: <strong>Plan ENTERPRISE</strong>. Deduplicación permite copiar inicialmente los 7TB (6-7 días a 100Mbps) y copias posteriores en minutos. <strong>Protección</strong>: Restauraciones a nivel de archivo con el Restore Wizard sin tener que descargar los 7TB. Protege contra Ransomware con inmutabilidad de snapshots en Wasabi S3.</p>',15)])])}const h=o(n,[["render",i]]);export{m as __pageData,h as default};
